export type AssetId = keyof typeof ASSETS;
export interface AssetMeta { path: string; width: number; height: number; frames: number }

// Animation clips derived from sprite-sheet metadata (run `assetgen index --frame-size`
// to populate frame grids). fps defaults to 12; tune per clip as needed.
export const ANIMATIONS = {
} as const;

export type AnimationId = keyof typeof ANIMATIONS;

/** Preload every asset as an HTMLImageElement, keyed by id. Browser-only. */
export async function loadAssets(base = "/assets/"): Promise<Record<AssetId, HTMLImageElement>> {
  const ids = Object.keys(ASSETS) as AssetId[];
  const loaded = await Promise.all(
    ids.map(
      (id) =>
        new Promise<[AssetId, HTMLImageElement]>((resolve, reject) => {
          const img = new Image();
          img.onload = () => resolve([id, img]);
          img.onerror = () => reject(new Error(`failed to load ${ASSETS[id].path}`));
          img.src = base + ASSETS[id].path;
        }),
    ),
  );
  return Object.fromEntries(loaded) as Record<AssetId, HTMLImageElement>;
}
